import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.Dg5fKO7V.js";const u=JSON.parse('{"title":"SonarQube","description":"","frontmatter":{},"headers":[],"relativePath":"SonarQube.md","filePath":"SonarQube.md","lastUpdated":1788563284000}'),i={name:"SonarQube.md"};function o(r,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="sonarqube" tabindex="-1">SonarQube <a class="header-anchor" href="#sonarqube" aria-label="Permalink to &quot;SonarQube&quot;">​</a></h1><p>AniSphere keeps its Sonar configuration in the application repository so a local SonarQube and the hosted pipeline evaluate the same sources, project rules and quality gate. Docker runs the local server and scanner; Node generates coverage and the repository-specific findings.</p><h2 id="start-the-local-server" tabindex="-1">Start the local server <a class="header-anchor" href="#start-the-local-server" aria-label="Permalink to &quot;Start the local server&quot;">​</a></h2><p>Install Docker Desktop or another Docker Compose installation, prepare the checkout as described under <a href="./Development-Setup">Development Setup</a>, then run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonar:up</span></span></code></pre></div><p>The first start downloads SonarQube Community and takes a few minutes. Open <code>http://localhost:9000</code> and wait until the server is ready. Generate tokens under <strong>My Account, Security</strong>. Keep tokens in the shell environment only; they do not belong in <code>.env</code>, a command committed to source control, or this documentation.</p><p>On PowerShell, set a token for the current terminal like this:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SONAR_TOKEN </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;your-token&#39;</span></span></code></pre></div><p>On macOS and Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SONAR_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;your-token&#39;</span></span></code></pre></div><p>Stop the containers with <code>npm run sonar:down</code>. The named Docker volumes keep findings and server configuration for the next start.</p><h2 id="prepare-a-fresh-instance" tabindex="-1">Prepare a fresh instance <a class="header-anchor" href="#prepare-a-fresh-instance" aria-label="Permalink to &quot;Prepare a fresh instance&quot;">​</a></h2><p>Quality profiles, projects and gates live in SonarQube&#39;s database. With an administrator token in <code>SONAR_TOKEN</code>, bootstrap a fresh server once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonar:provision</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonar</span></span></code></pre></div><p><code>sonar:provision</code> creates or updates <code>anisphere-frontend</code> and <code>anisphere-backend</code>, their separate quality gates and the committed JavaScript and TypeScript profiles. It defines new code as the last 30 days and is idempotent, so run it again whenever <code>scripts/sonar/config/</code> changes.</p><p>The provisioning token needs permission to administer quality profiles, quality gates and the project. Routine analysis can use a narrower token with <strong>Execute Analysis</strong> permission.</p><h2 id="run-an-analysis" tabindex="-1">Run an analysis <a class="header-anchor" href="#run-an-analysis" aria-label="Permalink to &quot;Run an analysis&quot;">​</a></h2><p>Install <code>cargo-llvm-cov</code> once with <code>cargo install cargo-llvm-cov --locked</code>, then run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonar</span></span></code></pre></div><p>The command always rebuilds its inputs before it scans, so stale reports cannot be uploaded:</p><ol><li>It runs <code>test:coverage:frontend</code> and <code>test:coverage:rust</code>, then normalizes Rust LCOV paths.</li><li>It writes separate frontend and backend project-check reports and asks Clippy for JSON findings.</li><li>It scans <code>.github/sonar-project.properties</code> and <code>.github/sonar-backend.properties</code>, waiting for both quality gates.</li></ol><p>Open <code>http://localhost:9000/dashboard?id=anisphere-frontend</code> and <code>http://localhost:9000/dashboard?id=anisphere-backend</code> for the results. Running only <code>npm run sonar:checks</code> is useful while editing a project rule, but it merely writes <code>.tool/sonar/external-issues-frontend.json</code> and <code>.tool/sonar/external-issues-backend.json</code>; the scanners import them. <code>.tool/</code> contains generated local reports only; all executable project and pipeline helpers are versioned under <code>scripts/</code>.</p><h2 id="project-specific-checks" tabindex="-1">Project-specific checks <a class="header-anchor" href="#project-specific-checks" aria-label="Permalink to &quot;Project-specific checks&quot;">​</a></h2><p>The project checks cover contracts that a general-purpose analyzer cannot infer:</p><ul><li>import cycles, feature boundaries, source roots, test placement and Tauri command boundaries</li><li>one shared Rust clock and the bounded AniList query and metadata-cache policy</li><li>matching frontend and backend error codes</li><li>file headers, public documentation, naming, comment style and configuration boundaries</li><li>localized copy, locale parity, encoding and placeholders</li><li>settled resource reads, adaptive CSS classes and static asset structure</li></ul><p>They are static analysis, not executable behaviour, so they do not live in Vitest or inflate test counts and coverage. Findings appear in Sonar with their own rule ids under the <code>anisphere-project</code> engine.</p><h2 id="quality-gate" tabindex="-1">Quality gate <a class="header-anchor" href="#quality-gate" aria-label="Permalink to &quot;Quality gate&quot;">​</a></h2><p>Both gates require no new issues, A security and reliability ratings, at most 3% duplicated lines on new code and all new security hotspots reviewed. Coverage stays separate so one half cannot hide the other:</p><table tabindex="0"><thead><tr><th>Project</th><th style="text-align:right;">Overall coverage</th><th style="text-align:right;">New-code coverage</th></tr></thead><tbody><tr><td><code>anisphere-frontend</code></td><td style="text-align:right;">at least 80%</td><td style="text-align:right;">at least 80%</td></tr><tr><td><code>anisphere-backend</code></td><td style="text-align:right;">at least 60%</td><td style="text-align:right;">at least 60%</td></tr></tbody></table><p>Vitest and <code>cargo llvm-cov</code> deliberately have no numeric threshold. They write the LCOV inputs; Sonar owns the two gates.</p><h2 id="hosted-pipeline" tabindex="-1">Hosted pipeline <a class="header-anchor" href="#hosted-pipeline" aria-label="Permalink to &quot;Hosted pipeline&quot;">​</a></h2><p>The <code>sonar-frontend</code> and <code>sonar-backend</code> jobs in <code>.github/workflows/quality.yml</code> become active when the repository defines <code>SONAR_ORGANIZATION</code> and the matching project-key variables. <code>SONAR_TOKEN</code> is an Actions secret. Each job generates its own coverage and external-issue report before uploading to SonarCloud; the backend job also imports Clippy.</p><p>Never put the token value in workflow YAML or a committed environment file.</p>`,33)])])}const k=a(i,[["render",o]]);export{u as __pageData,k as default};
